import{_ as a,C as r,c as i,o as n,a3 as t,G as o}from"./chunks/framework.Dokpd4od.js";const T=JSON.parse('{"title":"Log time","description":"","frontmatter":{},"headers":[],"relativePath":"master/services/timesheets/log-time.md","filePath":"master/services/timesheets/log-time.md","lastUpdated":1793074831000}'),l={name:"master/services/timesheets/log-time.md"};function h(m,e,d,g,c,p){const s=r("ImagePopup");return n(),i("div",null,[e[0]||(e[0]=t('<h1 id="log-time" tabindex="-1">Log time <a class="header-anchor" href="#log-time" aria-label="Permalink to &quot;Log time&quot;">​</a></h1><p>Logging time means adding a timesheet entry. You do it from the Timesheets page, where you pick the project and the task. Each task then shows its own time.</p><blockquote><p><strong>In simple words:</strong> Pick who worked, on what, on which day and for how many hours. Save, and the task totals update.</p></blockquote><p>Open <code>Project → Timesheets</code>.</p><div class="warning custom-block"><p class="custom-block-title">Prerequisites</p><ul><li><strong>Enable Timesheets</strong> is on.</li><li>The project has <strong>Allow Timesheets</strong>.</li><li>The project has at least one task.</li></ul><p>See <a href="./timesheet-settings.html">Timesheet settings</a>.</p></div><h2 id="add-a-timesheet-from-the-timesheets-page" tabindex="-1">Add a timesheet from the Timesheets page <a class="header-anchor" href="#add-a-timesheet-from-the-timesheets-page" aria-label="Permalink to &quot;Add a timesheet from the Timesheets page&quot;">​</a></h2><ol><li>Open <code>Project → Timesheets</code>.</li><li>Click <strong>Add Timesheet</strong>. The <strong>Create Timesheet</strong> window opens.</li></ol>',7)),o(s,{src:"/images1/timesheets/ts_add_timesheet_button.png",alt:"Timesheets page with the Add Timesheet button"}),e[1]||(e[1]=t('<ol start="3"><li>Fill in the form.</li></ol><ul><li><strong><em>Date:</em></strong> The day the work was done. Required.</li><li><strong><em>Employee:</em></strong> The person who did the work. Required. The list shows users with an Aureus login, not records from the Employees app. It does not fill in by itself, so choose your own name when you log your own time.</li><li><strong><em>Project:</em></strong> The project the work belongs to. Required. Only projects of your company are listed.</li><li><strong><em>Task:</em></strong> The task that received the work. Required. Choose a project first, because the list shows only tasks of that project.</li><li><strong><em>Description:</em></strong> A short note on what was done.</li><li><strong><em>Time Spent:</em></strong> Hours as a decimal number. Required. It cannot be below 0.</li></ul>',2)),o(s,{src:"/images1/timesheets/ts_add_timesheet_form.png",alt:"Add Timesheet form filled for Website Revamp and Migrate CMS content"}),e[2]||(e[2]=t('<div class="info custom-block"><p class="custom-block-title">Project then task</p><p>The <strong>Task</strong> list depends on the <strong>Project</strong>. If you change the project, the task is cleared. Pick the task again.</p></div><ol start="4"><li>Click <strong>Create</strong>. A message confirms the timesheet was created.</li></ol><h3 id="enter-hours-as-decimals" tabindex="-1">Enter hours as decimals <a class="header-anchor" href="#enter-hours-as-decimals" aria-label="Permalink to &quot;Enter hours as decimals&quot;">​</a></h3><p>Type time in hours. A quarter hour is 0.25. Half an hour is 0.5.</p><table tabindex="0"><thead><tr><th>You want</th><th>Type</th></tr></thead><tbody><tr><td>1 hour 30 minutes</td><td>1.5</td></tr><tr><td>2 hours 15 minutes</td><td>2.25</td></tr><tr><td>45 minutes</td><td>0.75</td></tr></tbody></table><h3 id="example" tabindex="-1">Example <a class="header-anchor" href="#example" aria-label="Permalink to &quot;Example&quot;">​</a></h3><p>Ava Lewis imported 40 articles on 14 Oct 2026. Enter these values:</p><ul><li><strong><em>Date:</em></strong> 14 Oct 2026</li><li><strong><em>Employee:</em></strong> Ava Lewis</li><li><strong><em>Project:</em></strong> Website Revamp</li><li><strong><em>Task:</em></strong> Migrate CMS content</li><li><strong><em>Description:</em></strong> Imported 40 articles</li><li><strong><em>Time Spent:</em></strong> 3</li></ul><p>Aureus sets the <strong>Creator</strong> to you. This is useful when you log time for someone else. You can group or filter by <strong>Creator</strong> in the <a href="./timesheet-list-and-filters.html">list</a>.</p><h2 id="see-the-time-on-a-task" tabindex="-1">See the time on a task <a class="header-anchor" href="#see-the-time-on-a-task" aria-label="Permalink to &quot;See the time on a task&quot;">​</a></h2><p>Every task shows its entries in a <strong>Timesheets</strong> tab. Use it to check the time of one task.</p><ol><li>Open <code>Project → Tasks</code> and open the task, for example <strong>Migrate CMS content</strong>.</li><li>Scroll down the <strong>View</strong> page and click the <strong>Timesheets</strong> tab.</li></ol>',12)),o(s,{src:"/images1/timesheets/ts_task_timesheets_tab.png",alt:"Time Tracking section and Timesheets tab of the task Migrate CMS content"}),e[3]||(e[3]=t('<p>The tab lists <strong>Date</strong>, <strong>Employee</strong>, <strong>Description</strong> and <strong>Time Spent</strong>. Rows at the bottom show the totals. See <a href="./timesheet-settings.html">Timesheet settings</a>.</p><h3 id="add-a-timesheet-from-the-task" tabindex="-1">Add a timesheet from the task <a class="header-anchor" href="#add-a-timesheet-from-the-task" aria-label="Permalink to &quot;Add a timesheet from the task&quot;">​</a></h3><ol><li>In the <strong>Timesheets</strong> tab, click <strong>Add Timesheet</strong>.</li><li>Fill in <strong>Date</strong>, <strong>Employee</strong>, <strong>Description</strong> and <strong>Time Spent</strong>. There is no <strong>Project</strong> or <strong>Task</strong> field. Aureus takes them from the task.</li><li>Click <strong>Create</strong>. The totals on the task update.</li></ol><div class="info custom-block"><p class="custom-block-title">INFO</p><p>The <strong>Timesheets</strong> tab appears only when <strong>Enable Timesheets</strong> is on and the project has <strong>Allow Timesheets</strong>. A task with no project also shows it.</p></div><h2 id="see-your-own-time" tabindex="-1">See your own time <a class="header-anchor" href="#see-your-own-time" aria-label="Permalink to &quot;See your own time&quot;">​</a></h2><p>On the Timesheets page, click the <strong>My Timesheets</strong> tab. It shows only entries where <strong>Employee</strong> is you. A number on the tab counts those entries.</p>',6)),o(s,{src:"/images1/timesheets/ts_my_timesheets_tab.png",alt:"My Timesheets tab showing only the logged in user's entries"}),e[4]||(e[4]=t('<h2 id="edit-an-entry" tabindex="-1">Edit an entry <a class="header-anchor" href="#edit-an-entry" aria-label="Permalink to &quot;Edit an entry&quot;">​</a></h2><ol><li>Find the entry in the Timesheets list.</li><li>Click <strong>Edit</strong> at the end of the row.</li><li>Change the values and save. A message confirms the timesheet was updated.</li></ol><p>Task totals are recalculated after the save.</p><h2 id="delete-an-entry" tabindex="-1">Delete an entry <a class="header-anchor" href="#delete-an-entry" aria-label="Permalink to &quot;Delete an entry&quot;">​</a></h2><ol><li>Click <strong>Delete</strong> at the end of the row.</li><li>Confirm. A message confirms the timesheet was deleted.</li></ol><p>Task totals are recalculated after the delete. To remove many entries at once, see <a href="./timesheet-list-and-filters.html">Timesheet list and filters</a>.</p><h2 id="actions-and-statuses" tabindex="-1">Actions and statuses <a class="header-anchor" href="#actions-and-statuses" aria-label="Permalink to &quot;Actions and statuses&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Action</th><th>Result</th></tr></thead><tbody><tr><td><strong>Add Timesheet</strong></td><td>Opens the form. <strong>Create</strong> saves the entry and adds its hours to the task.</td></tr><tr><td><strong>Edit</strong></td><td>Changes an entry and recalculates the task.</td></tr><tr><td><strong>Delete</strong></td><td>Removes an entry and recalculates the task.</td></tr></tbody></table><p>Timesheet entries have no status. They are saved as soon as you click <strong>Create</strong>.</p><h2 id="see-also" tabindex="-1">See also <a class="header-anchor" href="#see-also" aria-label="Permalink to &quot;See also&quot;">​</a></h2><ul><li><a href="./timesheet-list-and-filters.html">Timesheet list and filters</a></li><li><a href="./timesheet-settings.html">Timesheet settings</a></li><li><a href="./../project/task-management/sub-tasks.html">Sub tasks</a></li><li><a href="./../project/task-management/create-task.html">Create a task</a></li></ul>',11))])}const k=a(l,[["render",h]]);export{T as __pageData,k as default};
